"use client";

import * as React from "react";
import styles from "../styles/button.module.css";

type BuiltInIcon = "none" | "arrow" | "plus" | "download" | "sparkle" | "check";

export interface ButtonProps {
  /** Button text (ignored when children are passed) */
  label?: string;
  /** Custom content; overrides `label` */
  children?: React.ReactNode;
  /** Visual style */
  variant?: "default" | "secondary" | "outline" | "ghost" | "destructive" | "link";
  /** Size preset; `icon` renders a square icon-only button (uses `label` as its accessible name) */
  size?: "sm" | "md" | "lg" | "icon";
  /** Built-in inline SVG icon used when no custom icon slot is provided */
  icon?: BuiltInIcon;
  /** Where the built-in icon sits */
  iconPosition?: "leading" | "trailing";
  /** Custom leading icon slot (overrides the built-in icon) */
  leadingIcon?: React.ReactNode;
  /** Custom trailing icon slot (overrides the built-in icon) */
  trailingIcon?: React.ReactNode;
  /** Show a spinner and block interaction */
  loading?: boolean;
  /** Text shown while loading (defaults to the label) */
  loadingText?: string;
  /** Disable the button */
  disabled?: boolean;
  /** Scale applied while pressed (1 = none) */
  pressScale?: number;
  /** Brand color for the default and link variants */
  accentColor?: string;
  /** Stretch to the container width */
  fullWidth?: boolean;
  /** Render an <a> with this href instead of a <button> */
  href?: string;
  /** Anchor target when `href` is set */
  target?: string;
  /** Native button type */
  type?: "button" | "submit" | "reset";
  /** Click handler */
  onClick?: (event: React.MouseEvent<HTMLElement>) => void;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const ICON_PATHS: Record<Exclude<BuiltInIcon, "none">, string> = {
  arrow: "M5 12h14M13 6l6 6-6 6",
  plus: "M12 5v14M5 12h14",
  download: "M12 4v11M7 10l5 5 5-5M5 20h14",
  sparkle: "M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z",
  check: "M5 12.5l4.5 4.5L19 7",
};

function Icon({ name }: { name: Exclude<BuiltInIcon, "none"> }) {
  return (
    <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d={ICON_PATHS[name]} />
    </svg>
  );
}

export function Button({
  label = "Get started",
  children,
  variant = "default",
  size = "md",
  icon = "arrow",
  iconPosition = "trailing",
  leadingIcon,
  trailingIcon,
  loading = false,
  loadingText = "",
  disabled = false,
  pressScale = 0.97,
  accentColor = "#6366f1",
  fullWidth = false,
  href,
  target,
  type = "button",
  onClick,
  className = "",
  style,
}: ButtonProps) {
  const inactive = disabled || loading;
  const isIconOnly = size === "icon";
  const builtIn = icon !== "none" ? <Icon name={icon} /> : null;
  const lead = leadingIcon ?? (iconPosition === "leading" || isIconOnly ? builtIn : null);
  const trail = trailingIcon ?? (iconPosition === "trailing" && !isIconOnly ? builtIn : null);
  const text = loading && loadingText ? loadingText : children ?? label;

  const cls = [styles.root, styles[variant], styles[size], fullWidth ? styles.full : "", className].filter(Boolean).join(" ");
  const rootStyle = { "--mf-btn-accent": accentColor, "--mf-btn-press": String(pressScale), ...style } as React.CSSProperties;

  const content = (
    <>
      <span className={styles.spinnerSlot} data-on={loading || undefined} aria-hidden="true">
        <span className={styles.spinner} />
      </span>
      {lead && !(isIconOnly && loading) ? <span className={styles.glyph}>{lead}</span> : null}
      {isIconOnly ? null : <span className={styles.label}>{text}</span>}
      {trail ? <span className={`${styles.glyph} ${styles.trail}`}>{trail}</span> : null}
    </>
  );

  const shared = {
    className: cls,
    style: rootStyle,
    "data-loading": loading || undefined,
    "aria-busy": loading || undefined,
    "aria-label": isIconOnly ? label : undefined,
  };

  if (href) {
    return (
      <a
        {...shared}
        href={inactive ? undefined : href}
        target={target}
        rel={target === "_blank" ? "noreferrer noopener" : undefined}
        aria-disabled={inactive || undefined}
        role={inactive ? "link" : undefined}
        tabIndex={inactive ? 0 : undefined}
        onClick={(e) => {
          if (inactive) {
            e.preventDefault();
            return;
          }
          onClick?.(e);
        }}
      >
        {content}
      </a>
    );
  }

  return (
    <button {...shared} type={type} disabled={disabled} aria-disabled={loading || undefined} onClick={(e) => !inactive && onClick?.(e)}>
      {content}
    </button>
  );
}

.root {
  --mf-btn-h: 2.375rem;
  --mf-btn-px: 1rem;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  height: var(--mf-btn-h);
  padding: 0 var(--mf-btn-px);
  border: 1px solid transparent;
  border-radius: 0.5rem;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, box-shadow 160ms ease, opacity 160ms ease,
    transform 180ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.root:active:not(:disabled):not([aria-disabled="true"]) {
  transform: scale(var(--mf-btn-press, 0.97));
  transition-duration: 160ms, 160ms, 160ms, 160ms, 160ms, 80ms;
}

.root:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.root:disabled,
.root[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
}

.root[data-loading] {
  cursor: progress;
  opacity: 0.85;
}

/* Sizes */
.sm {
  --mf-btn-h: 2rem;
  --mf-btn-px: 0.75rem;
  font-size: 0.8125rem;
  border-radius: 0.4375rem;
}

.md {
  --mf-btn-h: 2.375rem;
}

.lg {
  --mf-btn-h: 2.75rem;
  --mf-btn-px: 1.375rem;
  font-size: 0.9375rem;
  border-radius: 0.625rem;
}

.glyph {
  display: inline-flex;
  flex-shrink: 0;
  transition: transform 200ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.root.icon {
  width: var(--mf-btn-h);
  padding: 0;
  gap: 0;
}

.full {
  display: flex;
  width: 100%;
}

.root:hover:not(:disabled):not([aria-disabled="true"]) .trail {
  transform: translateX(2px);
}

.label {
  display: inline-block;
}

/* Spinner: width animates from 0 so the label slides over */
.spinnerSlot {
  display: inline-grid;
  grid-template-columns: 0fr;
  margin-right: -0.5rem;
  opacity: 0;
  transition: grid-template-columns 200ms ease, margin 200ms ease, opacity 200ms ease;
}

.spinnerSlot[data-on] {
  grid-template-columns: 1fr;
  margin-right: 0;
  opacity: 1;
}

.root.icon .spinnerSlot {
  margin-right: 0;
}

.spinner {
  display: block;
  min-width: 0;
  width: 1rem;
  height: 1rem;
  overflow: hidden;
  border-radius: 999px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  animation: mf-btn-spin 700ms linear infinite;
}

@keyframes mf-btn-spin {
  to {
    transform: rotate(360deg);
  }
}

/* Variants */
.default {
  background-color: var(--mf-btn-accent, #6366f1);
  border-color: var(--mf-btn-accent, #6366f1);
  color: #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.default:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: color-mix(in srgb, var(--mf-btn-accent, #6366f1) 88%, #ffffff);
  box-shadow: 0 4px 14px -4px color-mix(in srgb, var(--mf-btn-accent, #6366f1) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.secondary {
  background-color: var(--mf-surface-raised, #1b1b22);
  color: var(--mf-fg, #f4f4f6);
}

.secondary:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: color-mix(in srgb, var(--mf-surface-raised, #1b1b22) 80%, var(--mf-fg, #f4f4f6));
}

.outline {
  background-color: var(--mf-surface, #141419);
  border-color: var(--mf-border, #2e2e38);
  color: var(--mf-fg, #f4f4f6);
}

.outline:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: var(--mf-surface-raised, #1b1b22);
  border-color: var(--mf-border-strong, #52525b);
}

.ghost {
  background-color: transparent;
  color: var(--mf-fg, #f4f4f6);
}

.ghost:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: var(--mf-surface-raised, #1b1b22);
}

.destructive {
  background-color: #dc2626;
  border-color: #dc2626;
  color: #ffffff;
}

.destructive:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: #b91c1c;
  border-color: #b91c1c;
}

.link {
  height: auto;
  padding: 0.125rem 0;
  background-color: transparent;
  color: var(--mf-btn-accent, #6366f1);
  background-image: linear-gradient(currentColor, currentColor);
  background-size: 0% 1px;
  background-position: 0 100%;
  background-repeat: no-repeat;
  border-radius: 0.25rem;
  transition: background-size 240ms cubic-bezier(0.16, 1, 0.3, 1), color 160ms ease, opacity 160ms ease;
}

.link:hover:not(:disabled):not([aria-disabled="true"]) {
  background-size: 100% 1px;
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .glyph,
  .spinnerSlot,
  .link {
    transition: none;
  }

  .root:active:not(:disabled):not([aria-disabled="true"]) {
    transform: none;
  }

  .root:hover .trail {
    transform: none;
  }

  .spinner {
    animation-duration: 1600ms;
  }
}

