"use client";

const variants = {
  default: "bg-indigo-500 text-white hover:bg-indigo-400",
  secondary: "bg-zinc-800 text-zinc-100 hover:bg-zinc-700",
  outline: "border border-zinc-800 bg-zinc-900 text-zinc-100 hover:bg-zinc-800",
  ghost: "text-zinc-100 hover:bg-zinc-800",
  destructive: "bg-red-600 text-white hover:bg-red-700",
  link: "text-indigo-400 underline-offset-4 hover:underline",
};

export function ButtonTailwind({ label = "Get started", variant = "default" as keyof typeof variants, loading = false }) {
  return (
    <button type="button" disabled={loading} aria-busy={loading} className={`group inline-flex h-9 items-center gap-2 rounded-lg px-4 text-sm font-medium transition active:scale-[0.97] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 disabled:opacity-60 ${variants[variant]}`}>
      {loading && <span aria-hidden="true" className="size-4 animate-spin rounded-full border-2 border-current border-r-transparent" />}
      {label}
      <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" className="transition-transform group-hover:translate-x-0.5"><path d="M5 12h14M13 6l6 6-6 6" /></svg>
    </button>
  );
}
